/*
  Normalisation, Filtrage 48h, Tagging Origine (90% Local/Afrique, 10% International)
*/
const items = $input.all();
const now = new Date();
const maxAgeHours = 48;

const normalized = [];

for (const item of items) {
  const json = item.json;
  const title = json.title || json.headline || '';
  const link = json.link || json.url || '';
  const pubDate = new Date(json.isoDate || json.pubDate || now);
  const content = json.contentSnippet || json.content || json.summary || '';
  const imageUrl = json.enclosure?.url || json.image?.url || json['media:content']?.url || null;

  // Check age < 48h
  const hoursDiff = (now - pubDate) / (1000 * 60 * 60);
  if (hoursDiff > maxAgeHours) continue;

  // Determine source & origin
  let sourceNom = 'SportFlow';
  let origine = 'local';

  if (link.includes('ivoirepoint')) {
    sourceNom = 'IvoirePoint';
    origine = 'local';
  } else if (link.includes('africatopsports')) {
    sourceNom = 'Africa Top Sports';
    origine = 'afrique';
  } else if (link.includes('sportnewsafrica')) {
    sourceNom = 'Sport News Africa';
    origine = 'afrique';
  } else if (link.includes('radiofrance') || link.includes('rfi')) {
    sourceNom = 'RFI Sport';
    origine = 'international';

    // Filter international: must contain African keywords
    const keywords = ['afrique', 'africain', 'can', 'cameroun', 'côte d\'ivoire', 'senegal', 'maroc', 'nigeria', 'algérie', 'ghana', 'osimhen', 'salah', 'hakimi', 'mane'];
    const lowerText = (title + ' ' + content).toLowerCase();
    const hasMatch = keywords.some(k => lowerText.includes(k));
    if (!hasMatch) continue;
  }

  normalized.push({
    json: {
      titre_original: title,
      source_url: link,
      source_nom: sourceNom,
      resume_original: content,
      image_url: imageUrl,
      created_at: pubDate.toISOString(),
      origine: origine
    }
  });
}

// Apply 90/10 distribution target (prioritize local & afrique)
const localOrAfrique = normalized.filter(i => i.json.origine !== 'international');
const international = normalized.filter(i => i.json.origine === 'international');

// Limit international to 10% of total selection
const targetInternationalCount = Math.ceil(localOrAfrique.length * 0.1);
const selectedInternational = international.slice(0, targetInternationalCount);

return [...localOrAfrique, ...selectedInternational];

