const items = $input.all();
const parsedItems = [];

for (let i = 0; i < items.length; i++) {
  try {
    const rawAiResponse = items[i].json.choices[0].message.content;
    // Clean markdown code blocks if any
    const cleanedJson = rawAiResponse.replace(/```json/g, '').replace(/```/g, '').trim();
    const aiData = JSON.parse(cleanedJson);

    const originalItem = $('Filtrage & Normalisation (90/10)').all()[i].json;

    parsedItems.push({
      json: {
        titre: aiData.titre || originalItem.titre_original,
        resume: aiData.resume || originalItem.resume_original,
        contenu: aiData.contenu || originalItem.resume_original,
        source_url: originalItem.source_url,
        source_nom: originalItem.source_nom,
        categorie: aiData.categorie || 'Football',
        image_url: originalItem.image_url,
        created_at: originalItem.created_at,
        origine: originalItem.origine
      }
    });
  } catch (err) {
    console.error('Erreur parsing JSON IA:', err);
  }
}

return parsedItems;
